import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.Y8If66rx.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/troubleshooting.md","filePath":"guide/troubleshooting.md"}'),n={name:"guide/troubleshooting.md"};function i(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="busmap-table-returns-a-registry-404" tabindex="-1"><code>@busmap/table</code> returns a registry 404 <a class="header-anchor" href="#busmap-table-returns-a-registry-404" aria-label="Permalink to &quot;`@busmap/table` returns a registry 404&quot;">​</a></h2><p>The current package README targets a configured Verdaccio registry, and <code>@busmap/table@0.1.1</code> is not available from the public npm registry at the time of writing. Configure the <code>@busmap</code> scope for the registry that hosts the package, or build and install a local tarball as described in <a href="./getting-started.html">Getting started</a>.</p><h2 id="react-peer-dependency-warning-or-hook-errors" tabindex="-1">React peer dependency warning or hook errors <a class="header-anchor" href="#react-peer-dependency-warning-or-hook-errors" aria-label="Permalink to &quot;React peer dependency warning or hook errors&quot;">​</a></h2><p>Prefer the latest stable React release, keeping React DOM and compatible type packages aligned across workspaces. This release declares the exact peer <code>react@19.3.1</code>, matching the current Bus Map application. For newer React versions, validate compatibility and use a table release whose peer declaration supports that version. A recommendation to upgrade does not override an exact peer constraint; do not suppress the warning.</p><h2 id="the-table-is-unstyled" tabindex="-1">The table is unstyled <a class="header-anchor" href="#the-table-is-unstyled" aria-label="Permalink to &quot;The table is unstyled&quot;">​</a></h2><p>Import <code>@busmap/table/style.css</code> from the application entry. Confirm that the bundler processes CSS from dependencies and that the stylesheet subpath is preserved in the installed package. The package does not automatically import the consumer&#39;s design-system theme.</p><h2 id="the-sorting-select-has-no-useful-options-or-throws" tabindex="-1">The sorting select has no useful options or throws <a class="header-anchor" href="#the-sorting-select-has-no-useful-options-or-throws" aria-label="Permalink to &quot;The sorting select has no useful options or throws&quot;">​</a></h2><p>The selector includes only leaf columns that TanStack reports as sortable. The sort-control hook throws if a sortable column has a non-string header. Provide text headers and enable sorting on the intended columns. A <code>Cannot sort column</code> error indicates that a selected/stored column ID is not a sortable column in the current table.</p><h2 id="a-resize-separator-does-not-move-the-expected-column" tabindex="-1">A resize separator does not move the expected column <a class="header-anchor" href="#a-resize-separator-does-not-move-the-expected-column" aria-label="Permalink to &quot;A resize separator does not move the expected column&quot;">​</a></h2><p>Pixel handles update their own width. Percentage handles transfer space against the nearest enabled percentage peer, or an enabled pixel partner when no percentage peer exists. Disabled columns are skipped. Check native <code>enableResizing</code>, <code>enableColumnResizing</code>, <code>columnResizeDirection</code>, pixel bounds, and the <a href="./column-sizing.html">sizing-mode guide</a>. Native defaults are 20px minimum and <code>Number.MAX_SAFE_INTEGER</code> maximum. In all-pixel tables, the last resizable column is the fallback; use an explicit percentage column for stable expansion.</p><p>A single percentage column already owns all remaining space. Without an enabled partner, no handle is shown. <code>enableResizing: false</code> on a percentage column disables interaction, not proportional expansion; use pixel mode for fixed width.</p><h2 id="a-virtualized-table-has-no-useful-scroll-area" tabindex="-1">A virtualized table has no useful scroll area <a class="header-anchor" href="#a-virtualized-table-has-no-useful-scroll-area" aria-label="Permalink to &quot;A virtualized table has no useful scroll area&quot;">​</a></h2><p><code>ResizableTable</code> owns the scroll element. Constrain its available height in the consuming layout; flex parents commonly need <code>min-height: 0</code>. Verify that the virtualized view is inside the intended scrolling region and that the browser provides <code>ResizeObserver</code>.</p><h2 id="a-theme-value-appears-ignored" tabindex="-1">A theme value appears ignored <a class="header-anchor" href="#a-theme-value-appears-ignored" aria-label="Permalink to &quot;A theme value appears ignored&quot;">​</a></h2><p>Set supported <code>--table-*</code> properties on the renderer&#39;s scroll container or an ancestor. Column width, column minimum width, and virtual position/height variables are calculated by the renderer; do not override those internal properties. Check the <a href="./../reference/api.html#css-custom-properties">CSS custom property reference</a>.</p><h2 id="a-row-doesn-t-activate-with-the-keyboard" tabindex="-1">A row doesn&#39;t activate with the keyboard <a class="header-anchor" href="#a-row-doesn-t-activate-with-the-keyboard" aria-label="Permalink to &quot;A row doesn&#39;t activate with the keyboard&quot;">​</a></h2><p><code>getRowProps</code> forwards attributes and handlers; it does not implement keyboard activation. Use a native button/link in the cell or provide and test the complete interaction in the consuming module.</p><h2 id="lego-graphs-tags-render-empty-in-the-table" tabindex="-1"><code>@lego/graphs</code> tags render empty in the table <a class="header-anchor" href="#lego-graphs-tags-render-empty-in-the-table" aria-label="Permalink to &quot;`@lego/graphs` tags render empty in the table&quot;">​</a></h2><p>Register the required Graph constructors with <code>customElements.define</code> once before the table view mounts. For the range-only example, the required tags are <code>lego-gantt</code>, <code>lego-gantt-row</code>, and <code>lego-gantt-date-range</code>. The guide draws its grid in CSS, so <code>lego-gantt-column-divider</code> is not required. Check that the view sets <code>date_domain</code> on the Gantt host and <code>data</code> on its row element as properties after mount; they are complex values, not string attributes.</p><h2 id="gantt-cells-have-no-range-or-render-at-the-wrong-width" tabindex="-1">Gantt cells have no range or render at the wrong width <a class="header-anchor" href="#gantt-cells-have-no-range-or-render-at-the-wrong-width" aria-label="Permalink to &quot;Gantt cells have no range or render at the wrong width&quot;">​</a></h2><p>Each Gantt row expects <code>data</code> items with a <code>date</code> timestamp or <code>[start, end]</code> timestamp pair and the matching <code>type</code>. Make sure the shared Gantt <code>date_domain</code> covers those timestamps and the cell&#39;s custom-element host uses <code>width: 100%</code>. The package&#39;s cell itself has overflow clipped, so give the Gantt column enough minimum width for the visualization.</p><h2 id="gantt-grid-lines-drift-after-sorting-resizing-or-scrolling" tabindex="-1">Gantt grid lines drift after sorting, resizing, or scrolling <a class="header-anchor" href="#gantt-grid-lines-drift-after-sorting-resizing-or-scrolling" aria-label="Permalink to &quot;Gantt grid lines drift after sorting, resizing, or scrolling&quot;">​</a></h2><p>In the inspected <code>@lego/graphs@0.0.1-rc30</code>, each Gantt instance keeps an initial tick anchor from its first time domain. Virtualized rows mount at different times, so internal column dividers can become misaligned between rows and with the header as the live domain advances. Sorting can expose different mounted instances; changing the divider interval alone does not remove the anchor difference.</p><p>Remove <code>lego-gantt-column-divider</code> from these cells. Draw a decorative, non-interactive CSS grid over each chart instead, using the same equal interval count as the header axis: four in this guide&#39;s example, five in Bus Map. Keep the header and grid at the full chart width without horizontal padding, and continue passing the same live <code>date_domain</code> to every chart. This fix belongs in the consumer integration, not the table package. See <a href="./gantt-column.html#add-a-typed-display-column">the shared-grid example</a> and <a href="./gantt-column.html#sorting-and-resizing">sorting and resizing checks</a>.</p><p>Verify grid boundaries against the header within one pixel after sorting both directions, resizing columns, advancing the clock, and scrolling to newly mounted rows. Also check the date-to-pixel scale, actual shadow-root canvas height, and range/point vertical center; aligned grid lines alone do not prove that the chart content is aligned. Wait for the asynchronous canvas width and scale updates to settle. Use a visible or headless browser: a hidden page can defer resize work and leave newly mounted canvases at zero width.</p><h2 id="many-gantt-cells-make-scrolling-slow" tabindex="-1">Many Gantt cells make scrolling slow <a class="header-anchor" href="#many-gantt-cells-make-scrolling-slow" aria-label="Permalink to &quot;Many Gantt cells make scrolling slow&quot;">​</a></h2><p>The Gantt row renderer starts its own canvas loop (60 FPS by default). Table virtualization limits mounted table rows, but every mounted Gantt still runs its own renderer. Reduce the number of simultaneous chart cells, profile the consumer page, or use a simpler static visualization when interaction is not needed. See the <a href="./gantt-column.html">Gantt-column guide</a>.</p>',28)])])}const g=t(n,[["render",i]]);export{p as __pageData,g as default};
